#!/usr/bin/env bash
# PreToolUse(Edit|Write): block edits of a flake.nix generated by flake-file.
# Detected by its DO-NOT-EDIT header, so hand-written devShell flakes stay editable.

event=$(cat)
file_path=$(echo "$event" | jq -r '.tool_input.file_path // empty')

case "$file_path" in
  */flake.nix|flake.nix)
    if head -n 1 "$file_path" 2>/dev/null | grep -q 'DO-NOT-EDIT.*flake-file'; then
      echo "flake.nix est auto-généré par flake-file. Pour le régénérer : nix run .#write-flake (depuis la racine de ce flake)" >&2
      exit 2
    fi
    ;;
esac

exit 0
